    function blockOf(id){
      let x = id, g = 0;
      while(x && NODE[x] && g++ < 40){ if(NODE[x].level === 2) return x; x = NODE[x].parent; }
      x = id; g = 0;
      while(x && NODE[x] && g++ < 40){ if(NODE[x].level === 1 && NODE[x].polity) return x; x = NODE[x].parent; }
      x = id; g = 0;
      while(x && NODE[x] && g++ < 40){ if(NODE[x].level === 0) return x; x = NODE[x].parent; }
      return null;
    }
    function dijkstra(src){
      const dist = {}, prev = {}; dist[src] = 0;
      const pq = [[0, src]];
      while(pq.length){
        pq.sort((a, b) => a[0] - b[0]);
        const cur = pq.shift(); const dv = cur[0], v = cur[1];
        if(dv > (dist[v] == null ? Infinity : dist[v])) continue;
        (ADJ[v] || []).forEach(x => {
          const nd = dv + x.days;
          if(nd < (dist[x.to] == null ? Infinity : dist[x.to])){ dist[x.to] = nd; prev[x.to] = v; pq.push([nd, x.to]); }
        });
      }
      return { dist: dist, prev: prev };
    }
    const descOf = (nid) => { const d = NODE[nid] || {}; return String(d.detail || d.brief || "").replace(/\n+/g, " ").trim(); };

    // ── ① 数据落地 ──
    let wrote = false, writeErr = "";
    function ensureGeo(){
      if (typeof getVariables !== "function") return null;
      let cur = null;
      try { cur = (getVariables({ type: "chat" }) || {})[GEO_KEY] || null; } catch (e) { cur = null; }
      if (cur && cur.v === VER) return cur;
      const obj = { v: VER, at: new Date().toISOString(), p: P, e: E, meta: META, colors: COLS, dash: DASH, width: WIDTH };
      try { insertOrAssignVariables({ [GEO_KEY]: obj }, { type: "chat" }); }
      catch (e) { writeErr = (e && e.message) || "unknown"; return null; }
      wrote = true;
      return obj;
    }

    // ── ② 位置 ──
    // 逐条从末尾往前取（getChatMessages(-i) 取倒数第 i 条）
    function tailMsgs(n){
      const out = [];
      if (typeof getChatMessages === "function") {
        for (let i = 1; i <= n; i++) {
          try {
            const a = getChatMessages(-i);
            const m = Array.isArray(a) ? a[0] : a;
            if (m) out.push(m);
          } catch (e) { void e; }
        }
      }
      if (!out.length) {
        try { if (typeof SillyTavern !== "undefined" && Array.isArray(SillyTavern.chat)) {
          const ch = SillyTavern.chat;
          for (let i = ch.length - 1; i >= 0 && out.length < n; i--) out.push(ch[i]);
        } } catch (e) { void e; }
      }
      return out;
    }
    function lastTp(){
      const list = tailMsgs(12);
      for (let i = 0; i < list.length; i++) {
        const s2 = list[i] && list[i].message;
        if (typeof s2 !== "string") continue;
        const r = s2.match(/<tp>([\s\S]*?)<\/tp>/);
        if (r) return r[1].trim();
      }
      return null;
    }
    function chatLenNow(){
      try { if (typeof SillyTavern !== "undefined" && Array.isArray(SillyTavern.chat)) return SillyTavern.chat.length; } catch (e) { void e; }
      try { if (typeof getLastMessageId === "function") { const id = getLastMessageId(); if (id != null && isFinite(id)) return Number(id) + 1; } } catch (e) { void e; }
      return null;
    }
    function lastUserText(){
      const list = tailMsgs(8);
      for (let i = 0; i < list.length; i++) {
        const m = list[i];
        if (!m) continue;
        if (m.role === "user" || m.is_user) return String(m.message || "");
      }
      return "";
    }
    function locationText(tp){
      let v = null;
      try { if (typeof getMessageVar === "function") v = getMessageVar("stat_data.世界.地点", { defaults: "" }); } catch (e) { void e; }
      if (v == null) {
        for (const mid of [-1, -2, -3]) {
          try {
            const mv = (typeof getVariables === "function") ? (getVariables({ type: "message", message_id: mid }) || {}) : {};
            const root = mv.stat_data ? mv : (mv.variables || mv);
            const sd = root && root.stat_data;
            const p = sd && sd["世界"] && sd["世界"]["地点"];
            if (p != null && p !== "") { v = p; break; }
          } catch (e) { void e; }
        }
      }
      const s = Array.isArray(v) ? v.join("-") : String(v == null ? "" : v).trim();
      if (s) return { text: s, src: "MVU 世界.地点" };
      return { text: tp || "", src: tp ? "<tp>" : "无" };
    }

    // ── ③ 匹配 ──
    const normT = t => String(t || "").trim().toLowerCase().replace(/\s+/g, "");
    const splitPath = t => String(t || "").split(/[-－—>＞/／,，、;；\n]+/).map(normT).filter(Boolean);
    function depthOf(id){ let d = 0, x = NODE[id], g = 0; while(x && x.parent && NODE[x.parent] && g++ < 40){ d++; x = NODE[x.parent]; } return d; }
    const cmpKey = (a, b) => { for (let i = 0; i < a.length; i++){ if(a[i] !== b[i]) return a[i] - b[i]; } return 0; };
    function resolveNode(tp){
      const loc = locationText(tp);
      const raw = loc.text;
      if(!raw) return { ok:false, why:"没有位置信息", src: loc.src, segs: [] };
      let body = raw;
      const at = body.lastIndexOf("@");
      if(at >= 0){ const bar = body.lastIndexOf("|"); body = (bar > at) ? body.slice(at + 1, bar) : body.slice(at + 1); }
      const segs = splitPath(body);
      if(!segs.length) return { ok:false, why:"位置串切不出有效段", src: loc.src, segs: [] };
      const whole = segs.join("");
      let best = null, bestId = null;
      Object.keys(NODE).forEach(id => {
        const nm = normT(NODE[id].name);
        if(!nm) return;
        const d = depthOf(id), imp = NODE[id].imp || 0;
        let score = null;
        if(whole === nm) score = [4, d, 4, 99, imp, nm.length];
        for(let i = 0; i < segs.length; i++){
          const sg = segs[i]; let sc = null;
          if(sg === nm) sc = [4, d, 3, i, imp, nm.length];
          else if(sg.indexOf(nm) >= 0) sc = [4, d, 2, i, imp, nm.length];
          if(sc && (!score || cmpKey(sc, score) > 0)) score = sc;
        }
        if(!score && whole.indexOf(nm) >= 0) score = [4, d, 1, -1, imp, nm.length];
        if(!score){
          for(let i = 0; i < segs.length; i++){
            const sg = segs[i];
            if(sg.length >= 2 && nm.indexOf(sg) >= 0){
              const ab = [3, d, 1, i, imp, nm.length];
              if(!score || cmpKey(ab, score) > 0) score = ab;
            }
          }
        }
        if(score && (!best || cmpKey(score, best) > 0)){ best = score; bestId = id; }
      });
      if(!bestId) return { ok:false, why:"没匹配上任何节点", src: loc.src, segs };
      return { ok:true, id: bestId, segs, src: loc.src };
    }

    // ── ④ 渲染 ──
    // 耗时/方式/地形（里程单独给出，不塞进交通方式里）
    function legsText(x){
      const arr = (x.legs && x.legs.length) ? x.legs : [{ tp: x.tp, days: x.days, terrain: x.terrain }];
      return arr.map(L => {
        let o = fmt(L.days);
        if(L.tp) o += "/" + L.tp;
        if(L.terrain) o += "/" + String(L.terrain).split("/").join("·");
        return o;
      }).join(" ｜ ");
    }

    function render(id){
      const L = [];
      const curBlk = blockOf(id);
      const blkTag = (nid) => {
        const b = blockOf(nid);
        if(!b || b === curBlk || b === nid) return "";
        const bn = NODE[b];
        if(!bn || bn.level === 0) return "";
        return "[" + bn.name + "]";
      };
      const d0 = descOf(id);
      L.push("【位置】" + chainOf(id).join(" › ") + (d0 ? ("：" + d0) : ""));

      const exits = ADJ[id] || [];
      const seen = {}; seen[id] = 1;
      exits.forEach(x => { seen[x.to] = 1; });
      const hopMap = {};
      exits.forEach(x => {
        (ADJ[x.to] || []).forEach(y => {
          if(seen[y.to]) return;
          seen[y.to] = 1;
          (hopMap[x.to] = hopMap[x.to] || []).push({ to: y.to, days: y.days });
        });
      });
      if(exits.length){
        L.push("【直通】");
        exits.forEach(x => {
          const t = NODE[x.to]; if(!t) return;
          const bd = bearing(id, x.to);
          const km = (x.km != null ? x.km : straightKm(id, x.to));
          const kmS = fmtKm(km);
          let head = "  " + (bd ? (bd + " → ") : "→ ") + t.name + blkTag(x.to);
          if(kmS) head += " (" + kmS + ")";
          head += "：" + legsText(x);
          const dt = descOf(x.to);
          if(dt) head += " —— " + dt;
          L.push(head);
          const h2 = (hopMap[x.to] || []).slice().sort((a, b) => a.days - b.days);
          if(h2.length) L.push("      ↳ " + h2.map(y => NODE[y.to].name + blkTag(y.to) + " 再" + fmt(y.days)).join("、"));
        });
      } else {
        L.push("【直通】此处无其他通路。");
      }

      // ── 邻接可达区域：只算直接相连的区块 ──
      const adjBlk = {};
      exits.forEach(x => {
        const b = blockOf(x.to);
        if(!b || b === curBlk) return;
        if(NODE[b].level === 0) return;
        if(!adjBlk[b] || x.days < adjBlk[b].days) adjBlk[b] = { b: b, days: x.days, via: x.to };
      });
      const adjList = Object.keys(adjBlk).map(k => adjBlk[k]).sort((a, b) => a.days - b.days);
      L.push("");
      if(adjList.length){
        L.push("【邻接可达区域】");
        adjList.forEach(o => {
          L.push("  " + NODE[o.b].name + " " + fmt(o.days) + "（经" + NODE[o.via].name + "）");
        });
      } else {
        L.push("【邻接可达区域】无（此处所有通路都在本区块内）");
      }

      // ── 主要势力 ──
      const pols = [];
      Object.keys(NODE).forEach(k => { const n = NODE[k]; if(n.level === 1 && n.polity) pols.push(n); });
      if(pols.length){
        pols.sort((a, b) => (b.imp || 0) - (a.imp || 0) || a.name.localeCompare(b.name, "zh"));
        const items = pols.map(n => "  " + n.name + " " + (n.brief || "").trim());
        L.push("");
        L.push("【主要势力】");
        items.forEach(x => L.push(x));
      }
      return L.join("\n");
    }

    // ── ⑤ 主流程 ──
    function update(opts){
      const o = opts || {};
      ensureGeo();
      const tp = lastTp();
      const r = resolveNode(tp);
      let text = "", at = null, why = "";
      if(r.ok){ at = r.id; text = render(r.id); }
      else { why = r.why || "未解析"; }
      const state = {
        v: VER, at: new Date().toISOString(),
        nodeId: at, nodeName: at ? NODE[at].name : null,
        blockName: at ? ((function(){ const b = blockOf(at); return b ? NODE[b].name : ""; })()) : null,
        segs: r.segs || null, segsSrc: r.src || null, why: why, text: text,
        chatLen: chatLenNow()
      };
      try { insertOrAssignVariables({ [STATE_KEY]: state }, { type: "chat" }); }
      catch (e) { say("状态写入失败：" + (e && e.message)); }
      if(o.notify){
        const tail = "｜数据 " + VER + (wrote ? "（新写入）" : "（已有）") + "｜" + P.length + " 地点";
        const vtag = "v" + SCRIPT_VER + " ";
        say(at ? (vtag + "当前位置：" + NODE[at].name + "（来源 " + (r.src || "?") + tail + "）")
             : (vtag + "位置未解析：" + why + "（来源 " + (r.src || "?") + tail + "）"));
        if(writeErr) say("地理数据写入失败：" + writeErr);
      }
      try { planRoute({ notify:false }); } catch (e) { void e; }
      return state;
    }

    // ── ⑥ 目的地规划 ──
    function matchPlaces(text){
      const t = String(text || "");
      if(!t) return [];
      const names = Object.keys(BY_NAME).filter(n => n && n.length >= 2);
      names.sort((a, b) => b.length - a.length);
      const hits = [], covered = [];
      for(let i = 0; i < names.length; i++){
        const nm = names[i];
        if(covered.some(c => c.indexOf(nm) >= 0)) continue;
        if(t.indexOf(nm) >= 0){ hits.push(BY_NAME[nm]); covered.push(nm); if(hits.length >= MAX_HITS) break; }
      }
      return hits;
    }
    const isVertex = id => !!(ADJ[id] && ADJ[id].length);
    function nearestVertexIn(id, dist){
      if(isVertex(id)) return id;
      let best = null;
      const stack = (CHILDREN[id] || []).slice(), guard = {};
      while(stack.length){
        const x = stack.pop();
        if(guard[x]) continue; guard[x] = 1;
        if(isVertex(x) && dist[x] != null){ if(best == null || dist[x] < dist[best]) best = x; }
        (CHILDREN[x] || []).forEach(y => stack.push(y));
      }
      return best;
    }
    // 单向靶点链：标题已声明起点，每段只写目标
    const blkAbs = (nid) => {
      const b = blockOf(nid);
      if(!b || b === nid) return "";
      const bn = NODE[b];
      if(!bn || bn.level === 0) return "";
      return "[" + bn.name + "]";
    };
    function routeText(prev, src, dst){
      const seq = []; let x = dst, g = 0;
      while(x && x !== src && g++ < 80){ seq.unshift(x); x = prev[x]; }
      seq.unshift(src);
      if(seq.length < 2) return { lines: [], segs: 0, km: 0 };
      const lines = [];
      let totalKm = 0, hasKm = false;
      for(let i = 0; i < seq.length - 1; i++){
        const a = seq[i], b = seq[i + 1];
        const e = (ADJ[a] || []).find(o => o.to === b);
        const km = (e && e.km != null) ? e.km : straightKm(a, b);
        const kmS = fmtKm(km);
        if(kmS){ totalKm += km; hasKm = true; }
        let ln = "  " + (i + 1) + ". → " + NODE[b].name + blkAbs(b);
        if(kmS) ln += " (" + kmS + ")";
        ln += "：" + (e ? legsText(e) : "?");
        lines.push(ln);
      }
      return { lines: lines, segs: seq.length - 1, km: hasKm ? totalKm : null };
    }
    // ── ⑥ 路线：目标持久化 + 文本指纹 ──
    function sigOf(t){
      const s = String(t || "");
      let h = 2166136261;
      for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = (h * 16777619) >>> 0; }
      return s.length + ":" + h;
    }
    function readRoute(){
      try { return (getVariables({ type: "chat" }) || {})[ROUTE_KEY] || null; } catch (e) { return null; }
    }
    function writeRoute(o){
      try { insertOrAssignVariables({ [ROUTE_KEY]: o }, { type: "chat" }); }
      catch (e) { say("行程写入失败：" + (e && e.message)); }
    }
    function emitRoute(cur, dests, sig, notify){
      const L = [];
      dests.forEach(raw => {
        const r = dijkstra(cur.id);
        const tv = nearestVertexIn(raw, r.dist);
        const head = "【最短路线】" + NODE[cur.id].name + blkAbs(cur.id) + " ➔ " + NODE[raw].name + blkAbs(raw);
        if(!tv || r.dist[tv] == null){ L.push(head + "：无已知路线"); L.push(""); return; }
        const rt = routeText(r.prev, cur.id, tv);
        const via = (tv !== raw) ? ("（经" + NODE[tv].name + "）") : "";
        const kmAll = (rt.km != null) ? (" 共" + Math.round(rt.km) + "km") : "";
        L.push(head + via + "｜" + rt.segs + "段" + kmAll + "｜最快" + fmt(r.dist[tv]));
        rt.lines.forEach(x => L.push(x));
        L.push("");
      });
      while(L.length && L[L.length - 1] === "") L.pop();
      const obj = {
        v: VER, at: new Date().toISOString(), turn: chatLenNow(),
        text: L.join("\n"), from: cur.ok ? NODE[cur.id].name : null,
        dests: dests.slice(), ask: sig
      };
      writeRoute(obj);
      if(notify) say("已生成最短路线 " + dests.length + " 条");
      return obj;
    }
    function planRoute(opts){
      const o = opts || {};
      ensureGeo();
      const cur = resolveNode(lastTp());
      const txt = lastUserText();
      const sig = sigOf(txt);
      const prev = readRoute();
      const hits = matchPlaces(txt);
      const live = cur.ok ? hits.filter(id => id !== cur.id) : hits;

      // 文本变了（发新消息 / 编辑消息 / 切换分支）：一律以新文本为准，没地名就清空
      if(!prev || prev.ask !== sig){
        if(!cur.ok || !live.length){
          writeRoute({
            v: VER, at: new Date().toISOString(), turn: chatLenNow(), text: "",
            from: cur.ok ? NODE[cur.id].name : null, dests: [], ask: sig,
            why: !cur.ok ? ("位置未解析：" + (cur.why || "")) : "本条消息未提及地名"
          });
          return null;
        }
        return emitRoute(cur, live, sig, o.notify);
      }

      // 文本没变：到点了收尾，换位置了重算，放太久了过期
      const dests = (prev.dests || []).filter(id => NODE[id]);
      if(!cur.ok) return prev;
      const todo = dests.filter(id => id !== cur.id);
      if(dests.length && !todo.length){
        writeRoute({
          v: VER, at: new Date().toISOString(), turn: chatLenNow(),
          text: "【行程】已抵达 " + NODE[cur.id].name, from: NODE[cur.id].name,
          dests: [], ask: sig, arrived: NODE[cur.id].name
        });
        return null;
      }
      if(todo.length && prev.from !== NODE[cur.id].name){
        return emitRoute(cur, todo, sig, o.notify);
      }
      const now = chatLenNow();
      if(prev.turn != null && now != null && now - prev.turn > ROUTE_TURNS){
        writeRoute({
          v: VER, at: new Date().toISOString(), turn: now, text: "",
          from: prev.from || null, dests: dests, ask: sig, why: "行程已过期"
        });
        return null;
      }
      return prev;
    }

    if (typeof eventOn === "function" && typeof tavern_events !== "undefined") {
      const EV = tavern_events;
      const sync = () => { try { update({ notify:false }); } catch (e) { void e; } };
      ["MESSAGE_RECEIVED","CHAT_CHANGED","MESSAGE_DELETED"].forEach(k => {
        if (EV[k]) { try { eventOn(EV[k], sync); } catch (e) { void e; } }
      });
      ["MESSAGE_EDITED","MESSAGE_UPDATED","MESSAGE_SWIPED"].forEach(k => {
        if (EV[k]) { try { eventOn(EV[k], () => { setTimeout(sync, 60); }); } catch (e) { void e; } }
      });
      const evSent = EV.MESSAGE_SENT || EV.GENERATION_AFTER_COMMANDS || null;
      if (evSent) { try { eventOn(evSent, () => { setTimeout(sync, 0); }); } catch (e) { void e; } }
    }

    const st = update({ notify:true });
    return st.nodeId ? ("已定位到 " + st.nodeName) : ("位置未解析：" + st.why);
})();
